/* Local approximate form study. Unitless geometry, no clinical/mechanical specification.
   All views share one mesh. WebGL lighting only; no image synthesis or third-party code. */
(async()=>{'use strict';
const verts=[],outline=[];
function line(a,b){outline.push(...a,0,0,1,1,1,1,...b,0,0,1,1,1,1);}
const sub=(a,b)=>a.map((v,i)=>v-b[i]);
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const norm=a=>{const n=Math.hypot(...a)||1;return a.map(v=>v/n)};
function tri(a,b,c,color,ns){const n=norm(cross(sub(b,a),sub(c,a)));[a,b,c].forEach((p,i)=>verts.push(...p,...(ns?ns[i]:n),...color));}
function quad(a,b,c,d,color,ns){tri(a,b,c,color,ns&&[ns[0],ns[1],ns[2]]);tri(a,c,d,color,ns&&[ns[0],ns[2],ns[3]]);}
const pearl=[.91,.925,.90],edge=[.79,.82,.80],steel=[.65,.70,.69],dark=[.24,.32,.30];
// Revolved profiles along the long X axis with softened shoulders.
function lathe(profile,color,segments=96){
 const pt=(x,r,t)=>[x,r*Math.cos(t),r*Math.sin(t)];
 for(const [x,r] of profile)for(let i=0;i<64;i++)line(pt(x,r,i*Math.PI/32),pt(x,r,(i+1)*Math.PI/32));
 for(let j=0;j<profile.length-1;j++)for(let i=0;i<12;i++)line(pt(...profile[j],i*Math.PI/6),pt(...profile[j+1],i*Math.PI/6));
 for(let j=0;j<profile.length-1;j++)for(let i=0;i<segments;i++){
 const a=i/segments*Math.PI*2,b=(i+1)/segments*Math.PI*2,[x,r]=profile[j],[xx,rr]=profile[j+1];
 const pt=(x,r,t)=>[x,r*Math.cos(t),r*Math.sin(t)];
 const normal=t=>norm([-(rr-r)/(xx-x||.001),Math.cos(t),Math.sin(t)]);
 quad(pt(x,r,a),pt(x,r,b),pt(xx,rr,b),pt(xx,rr,a),color,[normal(a),normal(b),normal(b),normal(a)]);
 }}
// Shaft and rounded rear shoulder.
lathe([[-1.55,.29],[-1.50,.34],[-1.40,.35],[-.15,.35],[.05,.42],[.35,.46],[1.12,.42],[1.40,.33],[1.50,.25]],pearl);
// Front cartridge sheath (approximate outer form, open annulus).
lathe([[-2.75,.385],[-2.70,.41],[-1.61,.41],[-1.55,.37]],steel);
lathe([[-2.77,.34],[-2.77,.40],[-2.71,.42],[-2.66,.40]],edge);
lathe([[-2.77,.335],[-2.38,.335]],dark);
lathe([[-2.38,.335],[-2.38,0]],dark);
// Fine longitudinal ribs, matching visible exterior lines rather than inventing mechanism.
for(let i=0;i<28;i++){const a=i*Math.PI*2/28,b=a+.013;const p=(x,t,r)=>[x,r*Math.cos(t),r*Math.sin(t)];quad(p(-2.66,a,.417),p(-2.66,b,.417),p(-1.63,b,.417),p(-1.63,a,.417),[.84,.86,.83]);}
lathe([[1.48,.23],[1.59,.245],[2.15,.245],[2.24,.20],[2.27,0]],pearl);
for(let i=0;i<12;i++){const a=i*Math.PI/6,b=a+.05;const p=(x,t)=>[x,.248*Math.cos(t),.248*Math.sin(t)];quad(p(1.68,a),p(1.68,b),p(2.10,b),p(2.10,a),edge);}
// Profile extrusion with bevel ring. Faces triangulated by ear clipping.
function area(ps){return ps.reduce((a,p,i)=>{let q=ps[(i+1)%ps.length];return a+p[0]*q[1]-q[0]*p[1]},0)}
function triangulate(poly){let ids=poly.map((_,i)=>i),out=[],guard=0;
 const orient=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
 while(ids.length>3&&guard++<1000){let found=false;for(let k=0;k<ids.length;k++){const a=ids[(k+ids.length-1)%ids.length],b=ids[k],c=ids[(k+1)%ids.length];if(orient(poly[a],poly[b],poly[c])<=0)continue;
 if(ids.some(i=>i!==a&&i!==b&&i!==c&&orient(poly[a],poly[b],poly[i])>=0&&orient(poly[b],poly[c],poly[i])>=0&&orient(poly[c],poly[a],poly[i])>=0))continue;
 out.push([a,b,c]);ids.splice(k,1);found=true;break;}if(!found)break;}if(ids.length===3)out.push(ids);return out;}
function profile(poly,thickness,color){for(let pass=0;pass<2;pass++){const out=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length];out.push([a[0]*.85+b[0]*.15,a[1]*.85+b[1]*.15],[a[0]*.15+b[0]*.85,a[1]*.15+b[1]*.85]);}poly=out;}if(area(poly)<0)poly.reverse();const center=poly.reduce((a,p)=>[a[0]+p[0]/poly.length,a[1]+p[1]/poly.length],[0,0]);const inner=poly.map(p=>[center[0]+(p[0]-center[0])*.95,center[1]+(p[1]-center[1])*.96]);
 const rings=[{p:inner,z:-thickness/2},{p:poly,z:-thickness/2+.055},{p:poly,z:thickness/2-.055},{p:inner,z:thickness/2}];
 for(const ring of [rings[0],rings[3]])for(let i=0;i<poly.length;i++)line([...ring.p[i],ring.z],[...ring.p[(i+1)%poly.length],ring.z]);
 for(let i=0;i<poly.length;i+=8)line([...rings[0].p[i],rings[0].z],[...rings[3].p[i],rings[3].z]);
 for(let j=0;j<3;j++)for(let i=0;i<poly.length;i++){let n=(i+1)%poly.length;quad([...rings[j].p[i],rings[j].z],[...rings[j].p[n],rings[j].z],[...rings[j+1].p[n],rings[j+1].z],[...rings[j+1].p[i],rings[j+1].z],color);}
 for(const [a,b,c] of triangulate(inner)){tri([...inner[a],thickness/2],[...inner[b],thickness/2],[...inner[c],thickness/2],color);tri([...inner[c],-thickness/2],[...inner[b],-thickness/2],[...inner[a],-thickness/2],color);}}
// Rear fixed grip, forward curved trigger and raised top block are visible in the source.
profile([[.45,.32],[1.13,.31],[1.31,.02],[1.34,-.35],[1.43,-.91],[1.48,-1.45],[1.43,-1.67],[1.26,-1.71],[1.12,-1.61],[1.00,-1.28],[.76,-.90],[.37,-.40],[.23,-.12]],.49,pearl);
profile([[.26,-.25],[.63,-.37],[.47,-.67],[.25,-1.00],[.19,-1.26],[.24,-1.49],[.47,-1.58],[.54,-1.68],[.33,-1.72],[.09,-1.61],[-.06,-1.40],[-.10,-1.10],[-.05,-.84],[.06,-.51]],.27,[.84,.865,.84]);
profile([[.08,.31],[.18,.74],[.72,.74],[.84,.32]],.48,pearl);
const mesh=new Float32Array(verts),wireMesh=new Float32Array(outline);
const vs=`attribute vec3 p,n,c;uniform mat3 rot;uniform float aspect,modelScale;varying vec3 N,C,P,O;void main(){O=p;vec3 v=rot*(p+vec3(.2,.45,0.));P=v;N=rot*n;C=c;float scale=modelScale;gl_Position=vec4(v.x*scale/aspect,v.y*scale,-v.z*.12,1.);}`;
const fs=`precision mediump float;varying vec3 N,C,P,O;uniform sampler2D logo;uniform float wireMode,colorMix;void main(){vec3 nn=normalize(N);if(!gl_FrontFacing)nn=-nn;vec3 l=normalize(vec3(-.5,.9,1.5));float d=max(dot(nn,l),0.);float fill=max(dot(nn,normalize(vec3(1.,.1,.5))),0.);float s=pow(max(dot(nn,normalize(l+vec3(0.,0.,1.))),0.),65.);vec3 col=C*(.60+.40*d+.08*fill)+vec3(1.,.95,.80)*s*.25;vec2 uv=vec2((O.x-.16)/.64,(.263666667-O.y)/.457333333);
 if(O.z<0.)uv.x=1.-uv.x;
 if(abs(O.z)>.16&&uv.x>=0.&&uv.x<=1.&&uv.y>=0.&&uv.y<=1.){vec4 mark=texture2D(logo,uv);col=mix(col,mark.rgb*(.85+.15*d),mark.a);}
 gl_FragColor=wireMode>1.5?vec4(0.,0.,0.,1.):wireMode>.5?vec4(vec3(1.),(1.-colorMix)*.65):vec4(col,colorMix);}`;
const logoImage=new Image();logoImage.src='data:image/png;base64,';await logoImage.decode();
let rendered=0;
for(const canvas of document.querySelectorAll('canvas')){const gl=canvas.getContext('webgl',{alpha:true,antialias:true,preserveDrawingBuffer:true});if(!gl){canvas.replaceWith(Object.assign(document.createElement('p'),{textContent:'這個瀏覽器尚未啟用 WebGL，請改用支援 WebGL 的瀏覽器查看模型。'}));continue;}
 const shader=(type,src)=>{let s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};
 const prog=gl.createProgram();gl.attachShader(prog,shader(gl.VERTEX_SHADER,vs));gl.attachShader(prog,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(prog);if(!gl.getProgramParameter(prog,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(prog));gl.useProgram(prog);
 const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,mesh,gl.STATIC_DRAW);['p','n','c'].forEach((name,i)=>{const a=gl.getAttribLocation(prog,name);gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,3,gl.FLOAT,false,36,i*12);});
 const texture=gl.createTexture();gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,texture);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,false);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,logoImage);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.uniform1i(gl.getUniformLocation(prog,'logo'),0);
 const solidBuffer=buffer,wireBuffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,wireBuffer);gl.bufferData(gl.ARRAY_BUFFER,wireMesh,gl.STATIC_DRAW);
 function bind(b){gl.bindBuffer(gl.ARRAY_BUFFER,b);['p','n','c'].forEach((name,i)=>{const a=gl.getAttribLocation(prog,name);gl.vertexAttribPointer(a,3,gl.FLOAT,false,36,i*12);});}
 const rot=gl.getUniformLocation(prog,'rot'),aspect=gl.getUniformLocation(prog,'aspect');
 function draw(){const d=Math.min(devicePixelRatio||1,2),w=canvas.clientWidth,h=canvas.clientHeight;if(canvas.width!==Math.round(w*d))canvas.width=Math.round(w*d);if(canvas.height!==Math.round(h*d))canvas.height=Math.round(h*d);gl.viewport(0,0,canvas.width,canvas.height);gl.enable(gl.DEPTH_TEST);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
 const y=Number(canvas.dataset.yaw),x=Number(canvas.dataset.pitch),cy=Math.cos(y),sy=Math.sin(y),cx=Math.cos(x),sx=Math.sin(x);
 const roll=Number(canvas.dataset.roll||0),cr=Math.cos(roll),sr=Math.sin(roll),m=[cy,sx*sy,-cx*sy,0,cx,sx,sy,-sx*cy,cx*cy];for(let j=0;j<9;j+=3){const a=m[j],b=m[j+1];m[j]=cr*a-sr*b;m[j+1]=sr*a+cr*b;}gl.uniformMatrix3fv(rot,false,new Float32Array(m));gl.uniform1f(aspect,w/h);gl.uniform1f(gl.getUniformLocation(prog,"modelScale"),Number(canvas.dataset.scale||.48));const mix=Number(canvas.dataset.mix??1);gl.uniform1f(gl.getUniformLocation(prog,'colorMix'),mix);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.depthFunc(gl.LEQUAL);{bind(solidBuffer);gl.uniform1f(gl.getUniformLocation(prog,'wireMode'),mix===0?2:0);gl.enable(gl.POLYGON_OFFSET_FILL);gl.polygonOffset(1,1);gl.drawArrays(gl.TRIANGLES,0,mesh.length/9);gl.disable(gl.POLYGON_OFFSET_FILL);}if(mix<1){bind(wireBuffer);gl.uniform1f(gl.getUniformLocation(prog,'wireMode'),1);gl.drawArrays(gl.LINES,0,wireMesh.length/9);}canvas.dataset.rendered='true';canvas.dataset.logo='loaded';}
 canvas.addEventListener('device-frame',e=>{for(const [k,v] of Object.entries(e.detail))canvas.dataset[k]=String(v);draw();});canvas.addEventListener('device-angle',e=>{canvas.dataset.yaw=String(e.detail.yaw);if(Number.isFinite(e.detail.pitch))canvas.dataset.pitch=String(e.detail.pitch);draw();});new ResizeObserver(draw).observe(canvas);draw();rendered++;
}
if(document.querySelector('#render-status'))document.querySelector('#render-status').textContent=`已載入 ${rendered} 個視角｜同一份本地模型・無外部下載・無自動旋轉`;
document.dispatchEvent(new Event(rendered?'device-ready':'device-error'));
})().catch(error=>{document.dispatchEvent(new Event('device-error'));const status=document.querySelector('#render-status');if(status)status.textContent='模型未載入，保留文字與照片預覽。';});
